315	// k8sValidation is one schema stage over one repository: the tools it has,
316	// what it validates against, and the report it fills in.
317	type k8sValidation struct {
318		target string
319		// scope is where helm and kustomize run, resolved once per stage.
320		scope       renderScope
321		kubeconform ToolSpec
322		opts        KubeconformOptions
323		report      *KubeconformReport
324	}
325	
326	// available reports whether an optional renderer was resolved at all.
327	func available(tool ToolSpec) bool {
328		return tool.Source != ToolSourceNone && tool.Source != ""
329	}
