377	// renderKustomizations builds and validates each overlay. Without kustomize,
378	// every overlay is reported as not rendered.
379	func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string) error {
380		tool := v.opts.Kustomize
381		for _, dir := range dirs {
382			if !available(tool) {
383				v.report.Unrendered = append(v.report.Unrendered, dir)
384				continue
385			}
386			file := path.Join(dir, k8s.KustomizationFile(filepath.Join(v.target, filepath.FromSlash(dir))))
387			scope := v.scope
388			if !v.opts.AllowRemoteBases {
389				scope = scope.cut()
390			}
391			cmd := kustomizeArgs(scope, dir, tool)
392			log.Printf("Running: %s", cmd.Loggable())
393			rendered, err := runner.Run(ctx, cmd, nil)
394			if err != nil {
395				if ctx.Err() != nil {
396					return ctx.Err()
397				}
398				repro, from := renderRepro(tool, "kustomize", "build", dir)
399				detail := failureDetail(err)
400				blocked := scope.offline && remoteBlocked(detail, from)
401				f := renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", from,
402					renderSteps(SourceKustomize, dir, from, detail, blocked), repro, err)
403				if blocked {
404					f.Title = remoteBlockedHeadline
405					f.Resolution = remoteBlockedResolution
406					// A copied `kustomize build` would run the refused fetch again, with
407					// the user's ssh agent and proxy, on a repository that is not trusted.
408					f.Repro = ""
409				}
410				v.report.Findings = append(v.report.Findings, f)
411				continue
412			}
413			// kustomize adds no origin to what it emits unless the kustomization
414			// asks for it, and DevDesk does not write into the file to ask. The
415			// overlay is what was built, so it is what a finding points at.
416			err = v.validateRendered(ctx, rendered, "kustomize", func(string, string) string { return file })
417			if err != nil {
418				return fmt.Errorf("overlay %s: %w", dir, err)
419			}
420		}
421		return nil
422	}
