552	// renderFailure is a chart or an overlay that could not be rendered: nothing
553	// in it was validated, and `helm install` or `kubectl apply -k` would fail the
554	// same way.
555	//
556	// steps and repro are what the caller wrote for it (renderSteps, localRepro);
557	// from is where the renderer ran.
558	func renderFailure(source, dialect, file, title string, from ToolSource, steps []string, repro string, err error) Finding {
559		detail := failureDetail(err)
560		first, _, _ := strings.Cut(detail, "\n")
561		return Finding{
562			ID:          K8sRenderID,
563			Title:       title + ": " + first,
564			Description: "The directory could not be rendered, so none of its resources were validated.",
565			Message:     detail,
566			Resolution:  renderResolution(source, from, detail),
567			Steps:       steps,
568			Repro:       repro,
569			RanFrom:     from,
570			Severity:    SeverityHigh,
571			Source:      source,
572			File:        file,
573			IaCType:     dialect,
574		}
575	}
576	
577	// failureDetail is what a renderer printed when it failed, or the error itself.
578	func failureDetail(err error) string {
579		var exitErr *exitError
580		if errors.As(err, &exitErr) && exitErr.Stderr != "" {
581			return strings.TrimSpace(exitErr.Stderr)
582		}
583		return err.Error()
584	}
