450	// helmLint runs helm lint and returns its warnings and errors. helm exits 1
451	// when a chart fails; its messages are still the answer. A run that printed
452	// nothing parseable is logged and yields nothing — the render that follows
453	// will say whether the chart is usable.
454	func helmLint(ctx context.Context, scope renderScope, chart string, tool ToolSpec) []Finding {
455		cmd := helmArgs(scope, chart, tool, "lint")
456		log.Printf("Running: %s", cmd.Loggable())
457		out, err := runner.Run(ctx, cmd, nil)
458		findings, recognised := parseHelmLint(out, chart, scope)
459		if err != nil && !recognised {
460			log.Printf("ERROR [scan/helm] lint %s: %v", logWord(chart), err)
461		}
462		repro, from := renderRepro(tool, "helm", "lint", chart)
463		for i := range findings {
464			findings[i].Repro, findings[i].RanFrom = repro, from
465		}
466		return findings
467	}
468	
469	// parseHelmLint turns helm lint's text into findings. The second result says
470	// the output was helm lint's at all.
471	//
472	// A message's path is usually relative to the chart ("templates/cm.yaml"),
473	// but not always: the missing-dependency warning names the chart directory
474	// absolutely — "/scan/charts/broken" in a container, measured on helm 4.3.0.
475	// Both are brought back to a path relative to the target.
476	func parseHelmLint(out []byte, chart string, scope renderScope) ([]Finding, bool) {
477		file := func(p string) string { return helmLintPath(p, chart, scope) }
478		var findings []Finding
479		recognised := false
480		sc := bufio.NewScanner(bytes.NewReader(out))
481		for sc.Scan() {
482			line := strings.TrimSpace(sc.Text())
483			switch {
484			case strings.HasPrefix(line, "==> Linting"):
485				recognised = true
486			case strings.HasPrefix(line, "Error "):
487				// Printed instead of the messages when the chart could not be
488				// loaded at all.
489				recognised = true
490				findings = append(findings, helmLintFinding(chart, chart, SeverityHigh, strings.TrimPrefix(line, "Error ")))
491			default:
492				m := helmLintLine.FindStringSubmatch(line)
493				if m == nil {
494					continue
495				}
496				recognised = true
497				switch m[1] {
498				case "ERROR":
499					findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityHigh, m[3]))
500				case "WARNING":
501					findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityLow, m[3]))
502				}
503			}
504		}
505		return findings, recognised
506	}
507	
508	// helmLintPath resolves a path helm lint printed to one relative to the
509	// target. In a container the target is the scope's working directory, which is
510	// /scan itself unless the git repository around the target is mounted.
511	func helmLintPath(p, chart string, scope renderScope) string {
512		p = strings.TrimSuffix(p, "/")
513		switch {
514		case p == containerScanPath || strings.HasPrefix(p, containerScanPath+"/"):
515			if rel, err := filepath.Rel(filepath.FromSlash(scope.workdir()), filepath.FromSlash(p)); err == nil {
516				return filepath.ToSlash(rel)
517			}
518			return p
519		case filepath.IsAbs(p):
520			if rel, err := filepath.Rel(scope.target, p); err == nil && !strings.HasPrefix(rel, "..") {
521				return filepath.ToSlash(rel)
522			}
523			return filepath.ToSlash(p)
524		default:
525			return path.Join(chart, p)
526		}
527	}
