305	// ── What the scan hands to helm, kustomize and kubeconform ───────────────────
306	
307	// networkRunner answers every tool of the schema stage with a success, or with
308	// kustomizeErr for `kustomize build`, and records what it was asked. git (asked
309	// for the mount of a container renderer) has no repository to name.
310	func networkRunner(t *testing.T, kustomizeErr string) *scriptedRunner {
311		t.Helper()
312		lint := "==> Linting charts/api\n\n1 chart(s) linted, 0 chart(s) failed\n"
313		r := &scriptedRunner{}
314		r.reply = func(tc toolCmd) ([]byte, error) {
315			if tc.Name == "git" {
316				return nil, &exitError{Code: 128, Stderr: "not a git repository"}
317			}
318			switch subcommandOf(tc) {
319			case "lint":
320				return []byte(lint), nil
321			case "template":
322				return []byte("apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: cm\n"), nil
323			case "build":
324				if kustomizeErr != "" {
325					return nil, &exitError{Code: 1, Stderr: kustomizeErr}
326				}
327				return []byte("apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: worker\n"), nil
328			}
329			return []byte(`{"resources":[]}`), nil
330		}
331		useRunner(t, r)
332		return r
333	}
334	
335	// callsTo is the recorded invocations that satisfy pred.
336	func (r *scriptedRunner) callsTo(pred func(toolCmd) bool) []toolCmd {
337		r.mu.Lock()
338		defer r.mu.Unlock()
339		var out []toolCmd
340		for _, c := range r.calls {
341			if pred(c) {
342				out = append(out, c)
343			}
344		}
345		return out
346	}
347	
348	// renderCall is the one invocation of a helm or kustomize subcommand.
349	func renderCall(t *testing.T, r *scriptedRunner, sub string) toolCmd {
350		t.Helper()
351		calls := r.callsTo(func(tc toolCmd) bool { return subcommandOf(tc) == sub })
352		if len(calls) != 1 {
353			t.Fatalf("%d calls of %q, want 1, among %q", len(calls), sub, r.commands())
354		}
355		return calls[0]
356	}
357	
358	// kubeconformCall is the invocation that validates what was rendered.
359	func kubeconformCall(t *testing.T, r *scriptedRunner) toolCmd {
360		t.Helper()
361		calls := r.callsTo(func(tc toolCmd) bool { return len(tc.Stdin) > 0 })
362		if len(calls) == 0 {
363			t.Fatalf("nothing was handed to kubeconform, among %q", r.commands())
364		}
365		return calls[0]
366	}
