753	// With the real kustomize and git, an overlay that names a remote base fails
754	// at once, with a message that says the transport was refused, and never with
755	// a name lookup: nothing left the machine.
756	func TestARealKustomizeIsRefusedItsRemoteBases(t *testing.T) {
757		kustomize := kustomizeWithGit(t)
758		isolateHome(t)
759		for _, c := range []struct{ name, resource string }{
760			{"ssh", "git@unreachable.invalid:o/r"},
761			{"https git", "https://unreachable.invalid/o/r.git"},
762			{"https resource", "https://unreachable.invalid/m.yaml"},
763			{"file", "file://FILEREPO"},
764		} {
765			t.Run(c.name, func(t *testing.T) {
766				// A git repository of this machine, which a transport of `file` would read.
767				local := t.TempDir()
768				if out, err := exec.CommandContext(t.Context(), "git", "init", "-q", local).CombinedOutput(); err != nil { //nolint:gosec // git on PATH, a fresh temp directory
769					t.Skipf("git init: %v: %s", err, out)
770				}
771				resource := strings.ReplaceAll(c.resource, "FILEREPO", filepath.ToSlash(local))
772				repo := writeRepo(t, map[string]string{"overlay/kustomization.yaml": "resources:\n  - " + resource + "\n"})
773	
774				start := time.Now()
775				report, err := RunKubeconform(t.Context(), repo, ToolSpec{Source: ToolSourceBinary, Binary: "kubeconform"},
776					KubeconformOptions{Kustomize: ToolSpec{Source: ToolSourceBinary, Binary: kustomize}}, nil)
777				elapsed := time.Since(start)
778	
779				if err != nil {
780					t.Fatalf("RunKubeconform: %v", err)
781				}
782				if elapsed.Seconds() >= 5 {
783					t.Errorf("took %s: something waited on the network", elapsed)
784				}
785				var render *Finding
786				for i, f := range report.Findings {
787					if f.ID == K8sRenderID {
788						render = &report.Findings[i]
789					}
790				}
791				if render == nil {
792					t.Fatalf("no render finding among %+v", report.Findings)
793				}
794				if strings.Contains(render.Message, "lookup unreachable.invalid") {
795					t.Errorf("the host was looked up, so the network was not cut:\n%s", render.Message)
796				}
797				if !strings.Contains(render.Message, "not allowed") && !strings.Contains(render.Message, "proxyconnect tcp: dial tcp 127.0.0.1:0") {
798					t.Errorf("no sign of a refused transport or of the dead proxy in:\n%s", render.Message)
799				}
800				if !remoteBlocked(render.Message, ToolSourceBinary) {
801					t.Errorf("remoteBlocked does not recognise what the real kustomize printed:\n%s", render.Message)
802				}
803				if !strings.Contains(render.Title, "remote base blocked") {
804					t.Errorf("title = %q, want it to say the remote base was blocked", render.Title)
805				}
806			})
807		}
808	}
