124	// valuesOf is every value env gives to name, in order.
125	func valuesOf(env []string, name string) []string {
126		var out []string
127		for _, kv := range env {
128			if v, ok := strings.CutPrefix(kv, name+"="); ok {
129				out = append(out, v)
130			}
131		}
132		return out
133	}
