170	// stepSamples calls every *Steps function of steps.go with inputs that reach each
171	// of its branches, and returns the lists it produced. TestEveryStepsFunctionHasASample
172	// fails when steps.go gains a function this map does not know, so a new one cannot
173	// escape the guard by being forgotten.
174	func stepSamples() map[string][][]string {
175		restrictor := loadRestrictorStderr
176		problem := kubeconformFieldProblem{Path: "/spec/replicas", Msg: "got string, want integer"}
177		unknownField := kubeconformFieldProblem{Path: "/spec/", Msg: "additional properties 'foo' not allowed"}
178		resource := kubeconformResource{Kind: "Deployment", Version: "apps/v1"}
179		return map[string][][]string{
180			"renderSteps": {
181				renderSteps(SourceHelm, "charts/api", ToolSourceBinary, "boom", false),
182				renderSteps(SourceKustomize, "overlays/dev", ToolSourceBinary, "boom", false),
183				renderSteps(SourceKustomize, "overlays/dev", ToolSourceBinary, restrictor, false),
184				renderSteps(SourceKustomize, "overlays/dev", ToolSourceContainer, restrictor, false),
185				renderSteps(SourceKustomize, "overlays/dev", ToolSourceContainer, "no such file or directory", false),
186				renderSteps(SourceKustomize, "overlays/dev", ToolSourceContainer, "evalsymlink failure", false),
187				// DEVDESK-767: a remote base the cut network refused.
188				renderSteps(SourceKustomize, "overlays/dev", ToolSourceBinary, sshBlockedStderr, true),
189				renderSteps(SourceKustomize, "overlays/dev", ToolSourceContainer, containerNoSuchHostStderr, true),
190			},
191			"helmLintSteps": {helmLintSteps("templates/deployment.yaml", "charts/api")},
192			"schemaSteps": {
193				schemaSteps(resource, problem, "1.36.0", ""),
194				schemaSteps(resource, problem, "", ""),
195				schemaSteps(resource, problem, "1.36.0", "helm"),
196				schemaSteps(resource, problem, "", "kustomize"),
197				schemaSteps(resource, unknownField, "1.36.0", ""),
198				schemaSteps(resource, kubeconformFieldProblem{Msg: "invalid"}, "1.36.0", ""),
199			},
200			"secretSteps": {secretSteps()},
201		}
202	}
