93	// afterOptions is files, preceded by the end of the options ("--", which Go's
94	// flag package honors) when one of them starts with "-": a file named
95	// -cache=x.yaml would otherwise be read as an option (DEVDESK-763). kubeconform
96	// reports a file under the name it was given, so the findings keep it. Ordinary
97	// names get no "--".
98	func afterOptions(files []string) []string {
99		for _, f := range files {
100			if strings.HasPrefix(f, "-") {
101				return append([]string{"--"}, files...)
102			}
103		}
104		return files
105	}
