107	// kubeconformFlags are the options every validation run shares, raw files or
108	// rendered input.
109	func kubeconformFlags(tool ToolSpec, opts KubeconformOptions) []string {
110		// The user's flags first: there is no subcommand, and Go's flag package
111		// stops at the first positional argument.
112		flags := append(append([]string{}, tool.Args...), "-output", "json", "-strict")
113		if opts.KubernetesVersion != "" {
114			flags = append(flags, "-kubernetes-version", opts.KubernetesVersion)
115		}
116		if opts.CacheDir != "" {
117			cache := opts.CacheDir
118			if tool.Source == ToolSourceContainer {
119				cache = kubeconformCacheMount
120			}
121			flags = append(flags, "-cache", cache)
122		}
123		return flags
124	}
