74	// useRunner swaps the package runner for the duration of the test. Production
75	// never reassigns it, so tests that do must not run in parallel.
76	func useRunner(t *testing.T, r commandRunner) {
77		t.Helper()
78		previous := runner
79		runner = r
80		t.Cleanup(func() { runner = previous })
81	}
