166	// validateFiles validates plain manifests, where each finding can be given the
167	// line its pointer designates.
168	func (v *k8sValidation) validateFiles(ctx context.Context, files []string, progressFn func(string)) error {
169		cmd := kubeconformArgs(v.target, files, v.kubeconform, v.opts)
170		log.Printf("Running: %s", cmd.Loggable())
171		out, err := runner.Run(ctx, cmd, progressFn)
172		if err := kubeconformFailure(out, err); err != nil {
173			return err
174		}
175		findings, skipped, err := parseKubeconformOutput(out, v.opts.KubernetesVersion, fileReader(v.target), nil)
176		if err != nil {
177			return err
178		}
179		v.stampSchemaRepro(findings)
180		v.report.Findings = append(v.report.Findings, findings...)
181		v.report.SkippedCustom += skipped
182		return nil
183	}
