15	// scriptedRunner stands in for the scanners. The reply is chosen per invocation
16	// so one scan can be given a different answer for each stage it runs, and the
17	// calls are recorded so a test can say which tool was asked what.
18	//
19	// It is locked because Scanner.Scan runs its stages concurrently.
20	type scriptedRunner struct {
21		mu       sync.Mutex
22		calls    []toolCmd
23		progress []string
24		reply    func(toolCmd) ([]byte, error)
25	}
26	
27	func (r *scriptedRunner) Run(_ context.Context, tc toolCmd, progressFn func(string)) ([]byte, error) {
28		r.mu.Lock()
29		r.calls = append(r.calls, tc)
30		lines := r.progress
31		r.mu.Unlock()
32	
33		if progressFn != nil {
34			for _, line := range lines {
35				progressFn(line)
36			}
37		}
38		return r.reply(tc)
39	}
40	
41	func (r *scriptedRunner) commands() []string {
42		r.mu.Lock()
43		defer r.mu.Unlock()
44		out := make([]string, 0, len(r.calls))
45		for _, c := range r.calls {
46			out = append(out, c.String())
47		}
48		return out
49	}
50	
51	// commandForStage returns the invocation of one stage, or "" if it never ran.
52	//
53	// Scan runs its stages concurrently, so calls are recorded in completion order:
54	// a test that wants one scanner's command has to name the stage. Taking the
55	// last command that merely looked like Trivy is how this went: two stages
56	// invoke Trivy, and whichever finished second won.
57	func (r *scriptedRunner) commandForStage(stage string) string {
58		r.mu.Lock()
59		defer r.mu.Unlock()
60		for _, c := range r.calls {
61			if stageOf(c) == stage {
62				return c.String()
63			}
64		}
65		return ""
66	}
67	
68	func (r *scriptedRunner) count() int {
69		r.mu.Lock()
70		defer r.mu.Unlock()
71		return len(r.calls)
72	}
73	
74	// useRunner swaps the package runner for the duration of the test. Production
75	// never reassigns it, so tests that do must not run in parallel.
76	func useRunner(t *testing.T, r commandRunner) {
77		t.Helper()
78		previous := runner
79		runner = r
80		t.Cleanup(func() { runner = previous })
81	}
82	
83	// answering builds a runner that gives every invocation the same reply.
84	func answering(t *testing.T, stdout string, err error) *scriptedRunner {
85		t.Helper()
86		r := &scriptedRunner{reply: func(toolCmd) ([]byte, error) { return []byte(stdout), err }}
87		useRunner(t, r)
88		return r
89	}

30	// HIGH finding with kustomize's whole message, like broken, which is broken
31	// wherever it is built.
32	func TestAnOverlayIsNotBlamedForWhatTheMountHides(t *testing.T) {
33		base, err := filepath.EvalSymlinks(t.TempDir())
34		if err != nil {
35			t.Fatal(err)
36		}
37		repo := filepath.Join(base, "repo")
38		useHome(t, filepath.Join(base, "home"), nil)
39		write := func(rel, content string) {
40			t.Helper()
41			p := filepath.Join(repo, filepath.FromSlash(rel))
42			mkdirs(t, filepath.Dir(p))
43			if err := os.WriteFile(p, []byte(content), 0o600); err != nil {
44				t.Fatal(err)
45			}
46		}
47		mkdirs(t, filepath.Join(repo, ".git"))
48		write("deploy/base/kustomization.yaml", "resources:\n- cm.yaml\n")
49		write("deploy/base/cm.yaml", "apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: base\n")
50		write("deploy/overlays/prod/kustomization.yaml", "resources:\n- ../../base\n")
51		write("deploy/overlays/broken/kustomization.yaml", "resources:\n- ../../missing\n")
52	
53		binary := ToolSpec{Source: ToolSourceBinary, Binary: "kustomize"}
54		image := ToolSpec{Source: ToolSourceContainer}
55		sub := filepath.Join(repo, "deploy", "overlays")
56		// want maps each overlay's kustomization, relative to the target, to the
57		// severity of its K8S-RENDER finding, "" for none.
58		tests := []struct {
59			name      string
60			target    string
61			kustomize ToolSpec
62			gitRoot   string // "" when git does not answer
63			want      map[string]SeverityLevel
64		}{
65			{"binary, repository root", repo, binary, repo, map[string]SeverityLevel{
66				"deploy/overlays/prod/kustomization.yaml": "", "deploy/overlays/broken/kustomization.yaml": SeverityHigh}},
67			{"binary, sub-directory", sub, binary, repo, map[string]SeverityLevel{
68				"prod/kustomization.yaml": "", "broken/kustomization.yaml": SeverityHigh}},
69			{"image, repository root", repo, image, repo, map[string]SeverityLevel{
70				"deploy/overlays/prod/kustomization.yaml": "", "deploy/overlays/broken/kustomization.yaml": SeverityHigh}},
71			{"image, sub-directory of a git repository", sub, image, repo, map[string]SeverityLevel{
72				"prod/kustomization.yaml": "", "broken/kustomization.yaml": SeverityHigh}},
73			{"image, sub-directory and no git", sub, image, "", map[string]SeverityLevel{
74				"prod/kustomization.yaml": SeverityHigh, "broken/kustomization.yaml": SeverityHigh}},
75		}
76		for _, tt := range tests {
77			t.Run(tt.name, func(t *testing.T) {
78				useRunner(t, &scriptedRunner{reply: func(tc toolCmd) ([]byte, error) {
79					if tc.Name == "git" {
80						if len(tc.Args) > 0 && tc.Args[0] == "config" {
81							return nil, &exitError{Code: 1} // core.worktree is not set
82						}
83						if tt.gitRoot == "" {
84							return nil, &exitError{Code: 128, Stderr: "fatal: not a git repository"}
85						}
86						return []byte(tt.gitRoot + "\n"), nil
87					}
