14	// What a step may say (docs/architecture/scanning.md, "Writing a Resolution,
15	// Steps and Repro for a new finding"). A step is an English US sentence with one
16	// action and no key name: the same fix is read in the finding detail, in `scan_result`
17	// and in the README, and a key name is true in only one of them.
18	//
19	// stepProblems checks what can be checked without judging prose:
20	//
21	//	S1  no key name: a modifier chord (ctrl+, alt+, shift+, cmd+), `esc` or `ctrl`
22	//	    on their own, a usual key name or a capital letter between angle brackets
23	//	    (<Y>, <Enter>; a placeholder such as <chart> is fine), a function key
24	//	    (F1 to F12), "<name> key" for a usual key name, "hit the key" or "hit the
25	//	    button", and the words press, keystroke, keybinding and shortcut;
26	//	S2  no step is empty, padded with blanks, or spread over several lines;
27	//	S3  a step starts with a capital letter, except the "move the file below ..." step
28	//	    right after the exact legacy step below;
29	//	S4  a step ends with a period, except the legacy step "Reference a directory that
30	//	    has its own kustomization.yaml, or" when "move the file below ..." follows it
31	//	    (the two-step alternative of a load restrictor failure, written before the
32	//	    convention and pinned by several tests and the cache: inherited, not a model);
33	//	S5  no step appears twice in the list.
34	//
35	// What it does not check, because no reliable check exists: that the first word is an
36	// imperative verb (a step may open with "If this reference points outside…"), that
37	// there is one action per step, and that the English is US. A bare "enter", "tab" or
38	// "return" is not flagged either: each is also an ordinary verb or noun.
39	var keyNamePatterns = []*regexp.Regexp{
40		regexp.MustCompile(`(?i)\b(?:ctrl|alt|shift|cmd|super)\+`),
41		regexp.MustCompile(`(?i)\b(?:ctrl|esc)\b`),
42		regexp.MustCompile(`<(?:Enter|Esc|Tab|Space|Ctrl|Alt|Shift|[A-Z])>`),
43		regexp.MustCompile(`\bF(?:[1-9]|1[0-2])\b`),
44		regexp.MustCompile(`(?i)\b(?:enter|return|esc|escape|tab|space|backspace|delete|arrow|up|down|left|right)\s+key\b`),
45		regexp.MustCompile(`(?i)\b(?:press|presses|pressed|pressing|keystrokes?|keybindings?|shortcuts?)\b`),
46		regexp.MustCompile(`(?i)\bhit\s+(?:the\s+)?(?:key|button)\b`),
